arguments.command:
cat <<'EOF' >> app/views/pwa/service_worker.js.erb

self.addEventListener("push", (event) => {
  if (!event.data) return

  const { title, options } = event.data.json()
  event.waitUntil(showNotification(title, options))
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()

  const path = event.notification.data?.path
  if (!path) return

  event.waitUntil(openNotificationPath(path))
})

async function showNotification(title, options) {
  await self.registration.showNotification(title, options)

  if ("setAppBadge" in self.navigator && options?.data?.badge != null) {
    try {
      await self.navigator.setAppBadge(options.data.badge)
    } catch {}
  }
}

async function openNotificationPath(path) {
  const targetUrl = new URL(path, self.location.origin)
  const windowClients = await self.clients.matchAll({ type: "window", includeUncontrolled: true })

  for (const client of windowClients) {
    const clientUrl = new URL(client.url)
    if (clientUrl.pathname === targetUrl.pathname && clientUrl.hash === targetUrl.hash && "focus" in client) {
      return client.focus()
    }
  }

  return self.clients.openWindow(targetUrl.href)
}
